(* [comment removed for export] *)
Definition wa14_rows_exit (sp gp tp : word) (F : bvmap 5 word) (fc : bv 32) (m : mem) (DR dn : Z) : machine_state -> Prop :=
  fun ms' => exists (ra' t0' t1' t2' s0' s1' a0' a1' a2' a3' a4' a5' a6' a7' s2' s3' s4' s5' s6' s7' s8' s9' s10' s11' t3' t4' t5' t6' : word) (m' : mem),
    ms' = MS (mkR ra' sp gp tp t0' t1' t2' s0' s1' a0' a1' a2' a3' a4' a5' a6' a7' s2' s3' s4' s5' s6' s7' s8' s9' s10' s11' t3' t4' t5' t6')
             F (Z_to_bv 64 0x139b84) fc None m' (seg_rom asegs)
    /\ munch [(DR, DR + dn)] m m' /\ wmono asegs m m' /\ mem_inv asegs m'.

(* [comment removed for export] *)
Lemma wa14_rows : forall (k : nat) (i : Z)
    (gp tp t2 a0 a2 a4 a5 s2 s5 s6 s7 s11 t4 t6 : word) F fc (m : mem) (FP dh dwb nfw lwb swpl dwpl PS0 PD0 SR sn DR dn : Z),
  Z.of_nat k = dh - i -> 0 <= i -> (1 <= k)%nat -> dh <= 20000 ->
  dwb = 32 * nfw + lwb -> 0 <= nfw -> 0 <= lwb < 32 -> 0 < dwb -> dwb <= 8 * 20000 ->
  0 < swpl <= 2^20 -> 0 < dwpl <= 2^20 -> swpl * dh <= 2^24 -> dwpl * dh <= 2^24 ->
  0 < SR -> SR mod 4 = 0 -> SR + sn <= 2^47 -> 0 < DR -> DR mod 4 = 0 -> DR + dn <= 2^47 -> PS0 mod 4 = 0 -> PD0 mod 4 = 0 ->
  (DR + dn <= 0x7fff7000 \/ 0x10007fff8000 <= DR) ->
  (forall i', 0 <= i' < dh -> SR <= PS0 + 4 * (swpl * i') /\ PS0 + 4 * (swpl * i') + 4 * (nfw + 1) <= SR + sn + 4 * (if lwb =? 0 then 1 else 0)) ->
  (forall i', 0 <= i' < dh -> DR <= PD0 + 4 * (dwpl * i') /\ PD0 + 4 * (dwpl * i') + 4 * (nfw + 1) <= DR + dn + 4 * (if lwb =? 0 then 1 else 0)) ->
  0 < FP -> FP mod 16 = 0 -> FP + 256 <= 2^47 -> (DR + dn <= FP \/ FP + 256 <= DR) ->
  rw_cells asegs m (FP + 72) [C8 (Z_to_bv 64 PD0); C8 (Z_to_bv 64 0)] ->
  rw_cells asegs m (FP + 136) [C8 (Z_to_bv 64 swpl); C8 (Z_to_bv 64 dwpl)] ->
  wr_at asegs m SR sn -> acc asegs m SR sn -> wr_at asegs m DR dn -> acc asegs m DR dn -> mem_inv asegs m ->
  evt asegs (wa14_rows_exit (Z_to_bv 64 FP) gp tp F fc m DR dn)
    (MS (mkR (Z_to_bv 64 18446744073709551611) (Z_to_bv 64 FP) gp tp (Z_to_bv 64 i) (Z_to_bv 64 2147450880) t2 (Z_to_bv 64 1) (Z_to_bv 64 PD0)
             a0 (Z_to_bv 64 swpl) a2 (Z_to_bv 64 (swpl * i)) a4 a5 (Z_to_bv 64 lwb) (Z_to_bv 64 (dwpl * i))
             s2 (Z_to_bv 64 dh) (Z_to_bv 64 dwb) s5 s6 s7 (Z_to_bv 64 0) (Z_to_bv 64 PS0) (Z_to_bv 64 (- nfw)) s11 (Z_to_bv 64 1) t4 (Z_to_bv 64 PS0) t6)
