(* [comment removed for export] *)
Lemma wa14_rows0 : forall (k : nat)
    (gp tp t2 a0 a2 a4 a5 s2 s5 s6 s7 s11 t4 t6 : word) F fc (m : mem) (FP dh dwb nfw lwb swpl dwpl PS0 PD0 SR sn DR dn : Z),
  Z.of_nat k = dh -> (1 <= k)%nat -> dh <= 20000 ->
  dwb = 32 * nfw + lwb -> 0 <= nfw -> 0 <= lwb < 32 -> 0 < dwb -> dwb <= 8 * 20000 ->
  0 < swpl <= 2^20 -> 0 < dwpl <= 2^20 -> swpl * dh <= 2^24 -> dwpl * dh <= 2^24 ->
